// Reference QR symbols for tests/qr-code.test.ts, generated by tests/fixtures/qr-reference.py
// with two independent encoders: segno 1.6.6 (whose padding-bit bug is patched there — it adds a
// whole 0x00 codeword when the terminator already ends on a codeword boundary, which ISO/IEC
// 18004 §7.4.10 does not) picks the version and, where none is forced, the mask by the §7.8.3
// penalty rules; python-qrcode 8 rebuilds every symbol at that version and mask and must agree
// module for module. `modules` packs the matrix row-major, most significant bit first, dark = 1.
// Regenerate: python3 -m venv v && v/bin/pip install segno==1.6.6 qrcode==8.2 &&
//   v/bin/python tests/fixtures/qr-reference.py  (prints the JSON this array holds).

/** One reference symbol. */
export interface QrReference {
  /** The encoded text (UTF-8, one byte-mode segment). */
  text: string;
  /** The error-correction level. */
  ecc: "L" | "M" | "Q" | "H";
  /** The version forced on the encoder, or `null` for the smallest that fits. */
  version: number | null;
  /** The mask forced on the encoder, or `null` for the lowest-penalty one. */
  mask: number | null;
  /** The version the reference encoders produced. */
  expectVersion: number;
  /** The mask the reference encoders produced. */
  expectMask: number;
  /** The matrix, packed (see the header). */
  modules: string;
}

